pragma solidity >=0.8.0;

contract IntDivCaptureBeforeCount {
    int8 public min8;
    int16 public min16;
    int64 public min64;
    int8 public r8;


    uint256 public count;

    constructor() {
        min8 = type(int8).min;
        min16 = type(int16).min;
        min64 = type(int64).min;
    }

    function div8() public returns (int8) {
        int8 r = min8 / int8(-1);
        r8 = r;
        count++;
        return r;
    }




}

